#nullable enable

class C
{
    public int M0(object obj) => 1;

    public void M1(C? c)
    {
        int x, y, z;
        _ = c?.M0(x = y = z = 1) != x // 1
            ? y.ToString() // 2
            : z.ToString();
    }

    public void M2(C? c)
    {
        int x, y, z;
        _ = x != c?.M0(x = y = z = 1) // 3
            ? y.ToString() // 4
            : z.ToString();
    }
}

